/// 前端按累计星星规则计算应得饰品后，同步入库；返回本次新解锁的 code
#[tauri::command]
pub async fn sync_unlocked_items(
    state: State<'_, SqlitePool>,
    input: ItemSyncInput,
) -> CmdResult<Vec<String>> {
    let mut newly = Vec::new();
    for code in input.item_codes {
