/// 兼容用的 execute 扩展
trait PoolExt {
    async fn execute(&self, sql: &str) -> Result<(), sqlx::Error>;
}

impl PoolExt for SqlitePool {
    async fn execute(&self, sql: &str) -> Result<(), sqlx::Error> {
        // 多语句在 SQLite 中可由一次 execute 顺序执行
        let mut conn = self.acquire().await?;
        let mut splitter = sql.split(';').peekable();
        while let Some(stmt) = splitter.next() {
            let trimmed = stmt.trim();
            if !trimmed.is_empty() {
                sqlx::query(trimmed).execute(&mut *conn).await?;
            }
        }
        Ok(())
    }
}

