/* ================= KidMath 全局样式（圆润卡通 / 高对比） ================= */
:root {
  --bg: #fef3e2;
  --bg2: #e0f2fe;
  --ink: #1f2937;
  --primary: #ff8a3d;
  --primary-dark: #ef6c00;
  --blue: #38bdf8;
  --green: #22c55e;
  --green-dark: #15803d;
  --pink: #fb7185;
  --purple: #a78bfa;
  --yellow: #fbbf24;
  --card: #ffffff;
  --shadow: 0 8px 0 rgba(0, 0, 0, 0.12);
  --radius: 28px;
  --good: #16a34a;
  font-size: 20px; /* 正文基准 ≥20px */
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  font-family: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB",
    "Noto Sans CJK SC", system-ui, sans-serif;
  color: var(--ink);
  background: linear-gradient(160deg, var(--bg) 0%, var(--bg2) 100%);
  overflow: hidden;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  outline: none;
}

/* ------------------------------ 通用按钮 ------------------------------ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 64px;
  padding: 12px 28px;
  font-size: 24px; /* 按钮文字 ≥24px */
  font-weight: 800;
  color: #fff;
  background: var(--primary);
  border-radius: 999px;
  box-shadow: 0 6px 0 var(--primary-dark);
  transition: transform 0.12s ease, box-shadow 0.12s ease, filter 0.12s ease;
}
.btn:hover {
  filter: brightness(1.05);
}
.btn:active {
  transform: scale(0.93);
  box-shadow: 0 2px 0 var(--primary-dark);
}
.btn.big {
  min-height: 88px;
  padding: 16px 40px;
  font-size: 28px;
  border-radius: 36px;
}
.btn.blue {
  background: var(--blue);
  box-shadow: 0 6px 0 #0284c7;
}
.btn.blue:active {
  box-shadow: 0 2px 0 #0284c7;
}
.btn.green {
  background: var(--green);
  box-shadow: 0 6px 0 var(--green-dark);
}
.btn.green:active {
  box-shadow: 0 2px 0 var(--green-dark);
}
.btn.gray {
  background: #94a3b8;
  box-shadow: 0 6px 0 #64748b;
}
.btn.gray:active {
  box-shadow: 0 2px 0 #64748b;
}
.btn.ghost {
  background: #fff;
  color: var(--ink);
  box-shadow: 0 6px 0 #cbd5e1;
}
.btn.ghost:active {
  box-shadow: 0 2px 0 #cbd5e1;
}
.btn.danger {
  background: #f87171;
  box-shadow: 0 6px 0 #b91c1c;
}
.btn.danger:active {
  box-shadow: 0 2px 0 #b91c1c;
}
.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

/* ------------------------------ 页面骨架 ------------------------------ */
.page {
  height: 100%;
  display: flex;
  flex-direction: column;
  padding: 22px 30px;
  animation: page-in 0.25s ease;
}
@keyframes page-in {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.99);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 14px;
}
.topbar .spacer {
  flex: 1;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: 0 10px 24px rgba(31, 41, 55, 0.1);
  padding: 24px;
}

/* 启动页 */
.splash {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
}
.splash-logo {
  font-size: 120px;
  animation: bob 1.6s ease-in-out infinite;
}
.splash-title {
  font-size: 56px;
  font-weight: 900;
  color: var(--primary-dark);
  letter-spacing: 4px;
}
@keyframes bob {
  0%,
  100% {
    transform: translateY(0) rotate(-4deg);
  }
  50% {
    transform: translateY(-14px) rotate(4deg);
  }
}

/* ------------------------------ 选择玩家 ------------------------------ */
.player-wrap {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 26px;
  padding: 30px;
  overflow: auto;
}
.player-title {
  font-size: 44px;
  font-weight: 900;
  margin: 0;
}
.player-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 26px;
  justify-content: center;
  max-width: 900px;
}
.player-card {
  width: 230px;
  min-height: 250px;
  background: var(--card);
  border-radius: 32px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 20px;
  border: 5px solid transparent;
  transition: transform 0.15s ease, border-color 0.15s ease;
}
.player-card:active {
  transform: scale(0.94);
}
.player-card.active {
  border-color: var(--yellow);
}
.player-card .avatar-face {
  font-size: 96px;
  line-height: 1;
}
.player-card .pname {
  font-size: 28px;
  font-weight: 800;
}
.player-card .pmeta {
  font-size: 20px;
  color: #64748b;
}
.player-card.add {
  border: 5px dashed #cbd5e1;
  color: #94a3b8;
  background: rgba(255, 255, 255, 0.7);
}
.player-card.add .plus {
  font-size: 88px;
  line-height: 1;
}

.parent-entry {
  position: absolute;
  bottom: 18px;
  right: 26px;
  font-size: 20px;
  color: #94a3b8;
  background: rgba(255, 255, 255, 0.8);
  border-radius: 999px;
  padding: 10px 20px;
  min-height: 48px;
}
.parent-entry:active {
  transform: scale(0.95);
}

/* ------------------------------ 表单 ------------------------------ */
.form-page {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  overflow: auto;
}
.form-card {
  width: 560px;
  max-width: 100%;
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.form-card h2 {
  margin: 0;
  font-size: 36px;
  text-align: center;
}
.field label {
  display: block;
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 8px;
}
.field input[type="text"],
.field input[type="date"],
.field input[type="password"],
.field select {
  width: 100%;
  min-height: 64px;
  font-size: 24px;
  border: 3px solid #cbd5e1;
  border-radius: 20px;
  padding: 8px 18px;
  font-family: inherit;
  background: #fff;
  color: var(--ink);
}
.field input:focus,
.field select:focus {
  border-color: var(--blue);
}
.avatar-picker {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.avatar-choice {
  width: 76px;
  height: 76px;
  font-size: 44px;
  border-radius: 22px;
  background: #f1f5f9;
  border: 4px solid transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.12s ease;
}
.avatar-choice:active {
  transform: scale(0.9);
}
.avatar-choice.sel {
  border-color: var(--primary);
  background: #fff7ed;
}
.form-actions {
  display: flex;
  gap: 14px;
  justify-content: center;
  margin-top: 6px;
}
.hint {
  font-size: 20px;
  color: #64748b;
}
.error-text {
  color: #dc2626;
  font-size: 20px;
  font-weight: 700;
  min-height: 26px;
  text-align: center;
}

/* ------------------------------ 首页 ------------------------------ */
.home-header {
  display: flex;
  align-items: center;
  gap: 18px;
  background: var(--card);
  border-radius: 32px;
  padding: 14px 24px;
  box-shadow: 0 8px 20px rgba(31, 41, 55, 0.08);
}
.home-header .avatar-face {
  font-size: 72px;
  line-height: 1;
}
.home-header .who h2 {
  margin: 0;
  font-size: 32px;
}
.home-header .who span {
  font-size: 20px;
  color: #64748b;
}
.star-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #fef3c7;
  color: #92400e;
  font-size: 26px;
  font-weight: 800;
  border-radius: 999px;
  padding: 10px 22px;
  min-height: 52px;
}
.home-scroll {
  flex: 1;
  overflow: auto;
  padding: 18px 4px 8px;
}
.game-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}
.game-tile {
  min-height: 170px;
  border-radius: 32px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: #fff;
  font-weight: 800;
  box-shadow: 0 8px 0 rgba(0, 0, 0, 0.15);
  transition: transform 0.14s ease, box-shadow 0.14s ease;
  text-align: center;
}
.game-tile:active {
  transform: scale(0.94) translateY(4px);
  box-shadow: 0 3px 0 rgba(0, 0, 0, 0.15);
}
.game-tile .gicon {
  font-size: 68px;
  line-height: 1;
}
.game-tile .gname {
  font-size: 30px;
}
.game-tile .gdesc {
  font-size: 20px;
  opacity: 0.95;
  font-weight: 600;
}
.game-tile .level-badge {
  margin-top: 4px;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 999px;
  font-size: 18px;
  padding: 4px 14px;
}
.soon-row {
  margin-top: 22px;
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  align-items: center;
}
.soon-tag {
  background: #e2e8f0;
  color: #64748b;
  border-radius: 999px;
  padding: 10px 20px;
  font-size: 20px;
  font-weight: 700;
}
.soon-label {
  font-size: 22px;
  font-weight: 800;
  color: #475569;
}
.home-actions {
  display: flex;
  gap: 14px;
  align-items: center;
}
.icon-btn {
  min-height: 56px;
  padding: 10px 22px;
  border-radius: 999px;
  font-size: 22px;
  font-weight: 800;
  background: #fff;
  color: var(--ink);
  box-shadow: 0 5px 0 #cbd5e1;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: transform 0.12s ease;
}
.icon-btn:active {
  transform: scale(0.93);
  box-shadow: 0 2px 0 #cbd5e1;
}

/* ------------------------------ 游戏容器 ------------------------------ */
.game-header {
  display: flex;
  align-items: center;
  gap: 14px;
}
.progress-dots {
  display: flex;
  gap: 8px;
  flex: 1;
  justify-content: center;
}
.dot {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #e2e8f0;
  transition: background 0.2s ease, transform 0.2s ease;
}
.dot.done {
  background: var(--green);
  transform: scale(1.1);
}
.dot.current {
  background: var(--yellow);
  box-shadow: 0 0 0 4px #fde68a;
}
.score-pill {
  background: #dcfce7;
  color: var(--green-dark);
  border-radius: 999px;
  padding: 8px 20px;
  font-size: 24px;
  font-weight: 800;
  min-height: 48px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.question-area {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  padding: 10px;
  overflow: auto;
}
.prompt {
  font-size: 38px;
  font-weight: 900;
  text-align: center;
}
.prompt .speak-btn {
  font-size: 30px;
  background: #e0f2fe;
  border-radius: 50%;
  width: 60px;
  height: 60px;
  margin-left: 10px;
  vertical-align: middle;
}
.prompt .speak-btn:active {
  transform: scale(0.9);
}
.answer-row {
  display: flex;
  gap: 18px;
  flex-wrap: wrap;
  justify-content: center;
}
.answer-btn {
  min-width: 110px;
  min-height: 88px;
  padding: 10px 26px;
  font-size: 40px;
  font-weight: 900;
  border-radius: 26px;
  background: #fff;
  color: var(--ink);
  border: 4px solid #cbd5e1;
  box-shadow: 0 6px 0 #cbd5e1;
  transition: transform 0.12s ease, background 0.12s ease, border-color 0.12s ease;
}
.answer-btn:active {
  transform: scale(0.92);
}
.answer-btn.correct-flash {
  background: #bbf7d0;
  border-color: var(--green);
  color: var(--green-dark);
  animation: pop 0.35s ease;
}
@keyframes pop {
  0% {
    transform: scale(1);
  }
  40% {
    transform: scale(1.18);
  }
  100% {
    transform: scale(1);
  }
}
.shake {
  animation: shake 0.4s ease;
}
@keyframes shake {
  0%,
  100% {
    transform: translateX(0);
  }
  20% {
    transform: translateX(-10px);
  }
  40% {
    transform: translateX(10px);
  }
  60% {
    transform: translateX(-7px);
  }
  80% {
    transform: x(7px);
  }
}

/* 捕鱼 */
.pond {
  position: relative;
  width: min(760px, 92%);
  height: 380px;
  border-radius: 32px;
  background: linear-gradient(180deg, #7dd3fc 0%, #0ea5e9 100%);
  overflow: hidden;
  box-shadow: inset 0 -10px 30px rgba(0, 0, 0, 0.12);
}
.fish {
  position: absolute;
  font-size: 52px;
  background: none;
  line-height: 1;
  padding: 6px;
  transition: transform 0.12s ease;
  filter: drop-shadow(0 3px 3px rgba(0, 0, 0, 0.2));
  animation: fishswim 3s ease-in-out infinite alternate;
}
.fish:active {
  transform: scale(0.85);
}
.fish.caught {
  animation: catchfish 0.45s ease forwards;
}
@keyframes catchfish {
  to {
    transform: scale(0) rotate(360deg);
    opacity: 0;
  }
}
@keyframes fishswim {
  from {
    margin-top: 0;
  }
  to {
    margin-top: -14px;
  }
}
.caught-counter {
  font-size: 30px;
  font-weight: 800;
  background: #fff;
  border-radius: 999px;
  padding: 8px 24px;
  box-shadow: 0 4px 0 #cbd5e1;
}

/* 比较 */
.compare-stage {
  display: flex;
  gap: 30px;
  align-items: stretch;
  justify-content: center;
  width: 100%;
}
.compare-side {
  flex: 1;
  max-width: 420px;
  min-height: 340px;
  background: #fff;
  border-radius: 32px;
  border: 6px solid #e2e8f0;
  box-shadow: 0 8px 0 #cbd5e1;
  padding: 18px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-content: flex-start;
  justify-content: center;
  transition: transform 0.12s ease, border-color 0.2s ease, background 0.2s ease;
}
.compare-side:active {
  transform: scale(0.96);
}
.compare-side.correct-flash {
  border-color: var(--green);
  background: #f0fdf4;
}
.compare-side .obj {
  font-size: 44px;
  line-height: 1.1;
}

/* 果园 */
.orchard-scene {
  font-size: 110px;
  line-height: 1;
  background: #ecfccb;
  border-radius: 32px;
  padding: 10px 40px;
  box-shadow: inset 0 0 0 4px #bef264;
}
.fruit-line {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  justify-content: center;
  max-width: 720px;
}
.fruit-line .f {
  font-size: 50px;
  transition: transform 0.2s ease, opacity 0.2s ease;
}
.fruit-line .f.taken {
  transform: scale(0);
  opacity: 0;
}
.fruit-line .f.added {
  animation: pop 0.3s ease;
}

/* 图形 & 规律 拖拽 */
.dnd-row {
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
}
.slot {
  width: 100px;
  height: 100px;
  border-radius: 24px;
  border: 5px dashed #94a3b8;
  background: rgba(255, 255, 255, 0.75);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0;
}
.slot.filled {
  border-style: solid;
  border-color: var(--green);
  background: #f0fdf4;
}
.slot.target-hot {
  border-color: var(--primary);
  background: #fff7ed;
  transform: scale(1.06);
}
.drag-piece {
  width: 100px;
  height: 100px;
  border-radius: 24px;
  background: #fff;
  box-shadow: 0 6px 0 #cbd5e1;
  display: flex;
  align-items: center;
  justify-content: center;
  touch-action: none;
  cursor: grab;
}
.drag-piece.dragging {
  opacity: 0.85;
  box-shadow: 0 12px 24px rgba(0, 0, 0, 0.25);
  cursor: grabbing;
  z-index: 50;
}
.drag-piece.bounce-back {
  animation: bounceback 0.3s ease;
}
@keyframes bounceback {
  0% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.12);
  }
  100% {
    transform: scale(1);
  }
}
.drag-piece.locked {
  box-shadow: none;
  background: #dcfce7;
}
.shape-svg {
  width: 74px;
  height: 74px;
}

/* 时钟 */
.clock-face {
  width: 300px;
  height: 300px;
}

/* ------------------------------ 粒子 ------------------------------ */
.particles {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 200;
  overflow: hidden;
}
.star-particle {
  position: absolute;
  font-size: 34px;
  animation: starfly 0.9s ease-out forwards;
}
@keyframes starfly {
  0% {
    transform: translate(0, 0) scale(0.4) rotate(0);
    opacity: 1;
  }
  100% {
    transform: translate(var(--dx), var(--dy)) scale(1.2) rotate(220deg);
    opacity: 0;
  }
}
.feedback-toast {
  position: fixed;
  top: 40%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 64px;
  font-weight: 900;
  color: var(--green-dark);
  background: rgba(255, 255, 255, 0.95);
  padding: 20px 50px;
  border-radius: 32px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
  z-index: 190;
  pointer-events: none;
  animation: toastpop 0.8s ease forwards;
}
@keyframes toastpop {
  0% {
    transform: translate(-50%, -50%) scale(0.5);
    opacity: 0;
  }
  25% {
    transform: translate(-50%, -50%) scale(1.1);
    opacity: 1;
  }
  70% {
    transform: translate(-50%, -50%) scale(1);
    opacity: 1;
  }
  100% {
    transform: translate(-50%, -70%) scale(0.95);
    opacity: 0;
  }
}

/* ------------------------------ 奖励页 ------------------------------ */
.reward-wrap {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  padding: 24px;
  overflow: auto;
}
.reward-card {
  width: min(620px, 96%);
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 14px;
  align-items: center;
}
.big-stars {
  font-size: 90px;
  letter-spacing: 10px;
}
.big-stars .earned {
  animation: pop 0.5s ease both;
}
.reward-stat {
  font-size: 28px;
  font-weight: 800;
}
.unlock-row {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  justify-content: center;
}
.unlock-chip {
  background: #fef3c7;
  border: 3px solid #fbbf24;
  border-radius: 22px;
  padding: 12px 18px;
  font-size: 22px;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 8px;
  animation: pop 0.45s ease both;
}
.reward-actions {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  justify-content: center;
}

/* ------------------------------ 图鉴 ------------------------------ */
.gallery-wrap {
  height: 100%;
  display: flex;
  flex-direction: column;
}
.gallery-scroll {
  flex: 1;
  overflow: auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 18px;
  align-content: start;
  padding: 8px 4px;
}
.item-card {
  background: #fff;
  border-radius: 24px;
  padding: 16px;
  text-align: center;
  box-shadow: 0 6px 0 #e2e8f0;
  border: 4px solid transparent;
  transition: transform 0.12s ease;
}
.item-card:active {
  transform: scale(0.95);
}
.item-card.equipped {
  border-color: var(--green);
  background: #f0fdf4;
}
.item-card.locked {
  filter: grayscale(1);
  opacity: 0.55;
}
.item-card .iemoji {
  font-size: 56px;
}
.item-card .iname {
  font-size: 22px;
  font-weight: 800;
}
.item-card .ineed {
  font-size: 18px;
  color: #92400e;
  font-weight: 700;
}

/* ------------------------------ 家长面板 ------------------------------ */
.parent-wrap {
  height: 100%;
  overflow: auto;
  padding: 26px 30px;
}
.parent-grid {
  display: grid;
  grid-template-columns: 360px 1fr;
  gap: 22px;
  max-width: 1100px;
  margin: 0 auto;
}
.pin-pad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.pin-key {
  min-height: 76px;
  font-size: 32px;
  font-weight: 900;
  border-radius: 22px;
  background: #fff;
  box-shadow: 0 5px 0 #cbd5e1;
  transition: transform 0.1s ease;
}
.pin-key:active {
  transform: scale(0.92);
  box-shadow: 0 2px 0 #cbd5e1;
}
.pin-dots {
  display: flex;
  gap: 14px;
  justify-content: center;
  margin: 10px 0 18px;
}
.pin-dot {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: 4px solid #94a3b8;
  background: #fff;
}
.pin-dot.on {
  background: var(--primary);
  border-color: var(--primary-dark);
}
.stat-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 20px;
}
.stat-table th,
.stat-table td {
  padding: 10px 8px;
  text-align: center;
  border-bottom: 2px solid #e2e8f0;
}
.stat-table th {
  color: #475569;
}
.level-stepper {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.level-stepper button {
  width: 48px;
  height: 48px;
  border-radius: 16px;
  font-size: 26px;
  font-weight: 900;
  background: #e0f2fe;
  color: #0369a1;
}
.range-row {
  display: flex;
  align-items: center;
  gap: 16px;
}
.range-row input[type="range"] {
  flex: 1;
  height: 12px;
  accent-color: var(--primary);
}
.range-val {
  font-size: 28px;
  font-weight: 900;
  min-width: 90px;
  text-align: center;
}
.child-list {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.section-title {
  font-size: 26px;
  font-weight: 900;
  margin: 0 0 12px;
}
.ach-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 12px;
}
.ach-chip {
  border-radius: 20px;
  padding: 12px;
  text-align: center;
  background: #f1f5f9;
  border: 3px solid transparent;
}
.ach-chip.got {
  background: #fef9c3;
  border-color: #facc15;
}
.ach-chip .aicon {
  font-size: 40px;
}
.ach-chip.dim .aicon {
  filter: grayscale(1);
  opacity: 0.4;
}
.ach-chip .atitle {
  font-size: 20px;
  font-weight: 800;
}
.ach-chip .adesc {
  font-size: 17px;
  color: #64748b;
}

/* 休息遮罩 */
.rest-overlay {
  position: fixed;
  inset: 0;
  z-index: 300;
  background: rgba(30, 41, 59, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  animation: page-in 0.25s ease;
}
.rest-card {
  background: #fff;
  border-radius: 40px;
  padding: 40px 50px;
  text-align: center;
  max-width: 520px;
}
.rest-card .remoji {
  font-size: 110px;
  animation: bob 2s ease-in-out infinite;
}
.rest-card h2 {
  font-size: 40px;
  margin: 8px 0;
}
.rest-card p {
  font-size: 24px;
  color: #475569;
}

@media (max-width: 900px) {
  .game-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .parent-grid {
    grid-template-columns: 1fr;
  }
}

toolUseResult.content:
/* ================= KidMath 全局样式（圆润卡通 / 高对比） ================= */
:root {
  --bg: #fef3e2;
  --bg2: #e0f2fe;
  --ink: #1f2937;
  --primary: #ff8a3d;
  --primary-dark: #ef6c00;
  --blue: #38bdf8;
  --green: #22c55e;
  --green-dark: #15803d;
  --pink: #fb7185;
  --purple: #a78bfa;
  --yellow: #fbbf24;
  --card: #ffffff;
  --shadow: 0 8px 0 rgba(0, 0, 0, 0.12);
  --radius: 28px;
  --good: #16a34a;
  font-size: 20px; /* 正文基准 ≥20px */
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  font-family: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB",
    "Noto Sans CJK SC", system-ui, sans-serif;
  color: var(--ink);
  background: linear-gradient(160deg, var(--bg) 0%, var(--bg2) 100%);
  overflow: hidden;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  outline: none;
}

/* ------------------------------ 通用按钮 ------------------------------ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 64px;
  padding: 12px 28px;
  font-size: 24px; /* 按钮文字 ≥24px */
  font-weight: 800;
  color: #fff;
  background: var(--primary);
  border-radius: 999px;
  box-shadow: 0 6px 0 var(--primary-dark);
  transition: transform 0.12s ease, box-shadow 0.12s ease, filter 0.12s ease;
}
.btn:hover {
  filter: brightness(1.05);
}
.btn:active {
  transform: scale(0.93);
  box-shadow: 0 2px 0 var(--primary-dark);
}
.btn.big {
  min-height: 88px;
  padding: 16px 40px;
  font-size: 28px;
  border-radius: 36px;
}
.btn.blue {
  background: var(--blue);
  box-shadow: 0 6px 0 #0284c7;
}
.btn.blue:active {
  box-shadow: 0 2px 0 #0284c7;
}
.btn.green {
  background: var(--green);
  box-shadow: 0 6px 0 var(--green-dark);
}
.btn.green:active {
  box-shadow: 0 2px 0 var(--green-dark);
}
.btn.gray {
  background: #94a3b8;
  box-shadow: 0 6px 0 #64748b;
}
.btn.gray:active {
  box-shadow: 0 2px 0 #64748b;
}
.btn.ghost {
  background: #fff;
  color: var(--ink);
  box-shadow: 0 6px 0 #cbd5e1;
}
.btn.ghost:active {
  box-shadow: 0 2px 0 #cbd5e1;
}
.btn.danger {
  background: #f87171;
  box-shadow: 0 6px 0 #b91c1c;
}
.btn.danger:active {
  box-shadow: 0 2px 0 #b91c1c;
}
.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

/* ------------------------------ 页面骨架 ------------------------------ */
.page {
  height: 100%;
  display: flex;
  flex-direction: column;
  padding: 22px 30px;
  animation: page-in 0.25s ease;
}
@keyframes page-in {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.99);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 14px;
}
.topbar .spacer {
  flex: 1;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: 0 10px 24px rgba(31, 41, 55, 0.1);
  padding: 24px;
}

/* 启动页 */
.splash {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
}
.splash-logo {
  font-size: 120px;
  animation: bob 1.6s ease-in-out infinite;
}
