  animation: pop 0.35s ease;
}
@keyframes pop {
  0% {
    transform: scale(1);
  }
  40% {
    transform: scale(1.18);
  }
  100% {
    transform: scale(1);
  }
}
.shake {
  animation: shake 0.4s ease;
}
@keyframes shake {
  0%,
  100% {
    transform: translateX(0);
  }
  20% {
    transform: translateX(-10px);
  }
  40% {
    transform: translateX(10px);
  }
  60% {
    transform: translateX(-7px);
  }
  80% {
    transform: x(7px);
  }
}

/* 捕鱼 */
.pond {
  position: relative;
  width: min(760px, 92%);
  height: 380px;
  border-radius: 32px;
  background: linear-gradient(180deg, #7dd3fc 0%, #0ea5e9 100%);
  overflow: hidden;
  box-shadow: inset 0 -10px 30px rgba(0, 0, 0, 0.12);
}
.fish {
  position: absolute;
  font-size: 52px;
  background: none;
  line-height: 1;
  padding: 6px;
  transition: transform 0.12s ease;
  filter: drop-shadow(0 3px 3px rgba(0, 0, 0, 0.2));
  animation: fishswim 3s ease-in-out infinite alternate;
}
.fish:active {
  transform: scale(0.85);
}
.fish.caught {
  animation: catchfish 0.45s ease forwards;
}
@keyframes catchfish {
  to {
    transform: scale(0) rotate(360deg);
    opacity: 0;
  }
}
@keyframes fishswim {
  from {
    margin-top: 0;
  }
  to {
    margin-top: -14px;
  }
}
.caught-counter {
  font-size: 30px;
  font-weight: 800;
  background: #fff;
  border-radius: 999px;
  padding: 8px 24px;
  box-shadow: 0 4px 0 #cbd5e1;
}

/* 比较 */
.compare-stage {
  display: flex;
  gap: 30px;
  align-items: stretch;
  justify-content: center;
  width: 100%;
}
.compare-side {
  flex: 1;
  max-width: 420px;
  min-height: 340px;
  background: #fff;
  border-radius: 32px;
  border: 6px solid #e2e8f0;
  box-shadow: 0 8px 0 #cbd5e1;
  padding: 18px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-content: flex-start;
  justify-content: center;
  transition: transform 0.12s ease, border-color 0.2s ease, background 0.2s ease;
}
