/* 图形 & 规律 拖拽 */
.dnd-row {
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
}
.slot {
  width: 100px;
  height: 100px;
  border-radius: 24px;
  border: 5px dashed #94a3b8;
  background: rgba(255, 255, 255, 0.75);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0;
}
.slot.filled {
  border-style: solid;
  border-color: var(--green);
  background: #f0fdf4;
}
.slot.target-hot {
  border-color: var(--primary);
  background: #fff7ed;
  transform: scale(1.06);
}
.drag-piece {
  width: 100px;
  height: 100px;
  border-radius: 24px;
  background: #fff;
  box-shadow: 0 6px 0 #cbd5e1;
  display: flex;
  align-items: center;
  justify-content: center;
  touch-action: none;
  cursor: grab;
}
.drag-piece.dragging {
  opacity: 0.85;
  box-shadow: 0 12px 24px rgba(0, 0, 0, 0.25);
  cursor: grabbing;
  z-index: 50;
}
.drag-piece.bounce-back {
  animation: bounceback 0.3s ease;
}
@keyframes bounceback {
  0% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.12);
  }
  100% {
    transform: scale(1);
  }
}
.drag-piece.locked {
  box-shadow: none;
  background: #dcfce7;
}
.shape-svg {
  width: 74px;
  height: 74px;
}

/* 时钟 */
.clock-face {
  width: 300px;
