    // 高级别选项补满 4 个
    while (choiceSet.size < Math.min(4, max + 1)) {
      const c = randInt(1, max, rng);
      choiceSet.add(c);
    }
    const fish = Array.from({ length: count }, () => ({
      emoji: FISH_EMOJIS[randInt(0, FISH_EMOJIS.length - 1, rng)],
      top: 8 + rng() * 78,
      left: 4 + rng() * 86,
      delay: rng() * 2,
      flip: rng() > 0.5,
    }));
    return {
      count,
      fish,
      choices: [...choiceSet].sort((a, b) => a - b),
    };
  });
}

export default function Fishing({
  level,
  onDone,
}: {
  level: number;
  onDone: (c: number, t: number) => void;
}) {
  const questions = useMemo(() => buildQuestions(level), [level]);
  const { idx, correct, locked, submit, total } = useRound(questions, onDone);
  const q = questions[idx];
  const [caught, setCaught] = useState<boolean[]>(() => q.fish.map(() => false));
  const [caughtCount, setCaughtCount] = useState(0);
  const fb = useFeedback();

  const catchFish = (i: number, ev: React.MouseEvent<HTMLButtonElement>) => {
    if (locked || caught[i]) return;
    const next = caught.slice();
    next[i] = true;
    setCaught(next);
    const n = caughtCount + 1;
    setCaughtCount(n);
    fb.good(ev.currentTarget);
  };

  const choose = (n: number, ev: React.MouseEvent<HTMLButtonElement>) => {
    if (locked) return;
    const ok = n === q.count;
    const result = submit(ok);
    if (result === "right") {
      fb.good(ev.currentTarget);
      // 进入下一题前重置捕鱼状态
      window.setTimeout(() => {
        const nq = questions[Math.min(idx + 1, questions.length - 1)];
        setCaught(nq.fish.map(() => false));
        setCaughtCount(0);
      }, 500);
    } else if (result === "retry") {
      fb.gentleWrong(ev.currentTarget);
    }
  };

  return (
    <div className="question-area">
      <FeedbackLayer burst={fb.burst} toast={fb.toast} />
      <SpeakPrompt text={`数一数，池塘里一共有几条鱼？`}>
        数一数，池塘里有几条鱼？
      </SpeakPrompt>

      <div className="caught-counter">
        已捕到 🐟 × {caughtCount}
      </div>

      <div className="pond" key={idx}>
        {q.fish.map((f, i) => (
          <button
            key={i}
            className={`fish ${caught[i] ? "caught" : ""}`}
            style={{
              top: `${f.top}%`,
              left: `${f.left}%`,
              animationDelay: `${f.delay}s`,
              transform: f.flip ? "scaleX(-1)" : undefined,
            }}
            onClick={(e) => catchFish(i, e)}
            aria-label="鱼"
          >
            {f.emoji}
          </button>
        ))}
      </div>

      <div className="answer-row">
        {q.choices.map((c) => (
          <button key={c} className="answer-btn" onClick={(e) => choose(c, e)}>
            {c}
          </button>
        ))}
      </div>

      <div className="hint">
        第 {idx + 1} / {total} 题 · 答对 {correct} 题
      </div>
    </div>
  );
}

