      A: shapes[0],
      B: shapes[1 % shapes.length],
      C: shapes[2 % shapes.length],
    } as Record<"A" | "B" | "C", ShapeKind>;
    const palette = keys.map((k, i) => ({ color: colors[i % colors.length].value }));

    // 选项：正确答案 + 干扰
    const needed = new Set(blanks.map((b) => seq[b]));
