import { useRef, useState } from "react";

/** 4 位数字 PIN 键盘（误码抖动，不显示叉） */
export default function PinPad({
  onSuccess,
}: {
  onSuccess: () => void | Promise<void>;
}) {
  const [pin, setPin] = useState("");
  const [shake, setShake] = useState(false);
  const [checking, setChecking] = useState(false);
  const verifyRef = useRef<(p: string) => Promise<boolean>>();
  verifyRef.current = async (p: string) =>
    (await import("../lib/api")).api.verifyPin(p);

  const tap = (k: string) => {
    if (checking) return;
    if (k === "del") {
      setPin((p) => p.slice(0, -1));
      return;
    }
    if (pin.length >= 4) return;
    const next = pin + k;
    setPin(next);
    if (next.length === 4) {
      setChecking(true);
      window.setTimeout(async () => {
        const ok = await verifyRef.current!(next);
        if (ok) {
          await onSuccess();
        } else {
          setShake(true);
          window.setTimeout(() => setShake(false), 450);
          setPin("");
        }
        setChecking(false);
      }, 120);
    }
  };

  const keys = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "del", "0", "ok"];

  return (
    <div className={`card ${shake ? "shake" : ""}`} style={{ width: 380 }}>
      <h2 className="section-title" style={{ textAlign: "center" }}>
        👪 家长验证
      </h2>
      <div className="hint" style={{ textAlign: "center" }}>
        请输入 4 位家长 PIN（初始为 0000）
      </div>
      <div className="pin-dots">
        {[0, 1, 2, 3].map((i) => (
          <span key={i} className={`pin-dot ${pin.length > i ? "on" : ""}`} />
        ))}
      </div>
      <div className="pin-pad">
        {keys.map((k) => (
          <button
            key={k}
            className="pin-key"
            onClick={() => k === "ok" || tap(k)}
            style={k === "del" ? { fontSize: 26 } : undefined}
          >
            {k === "del" ? "⌫" : k}
          </button>
        ))}
      </div>
    </div>
  );
}

