                : "确定要永久删除这个孩子的档案吗？"}
            </span>
            <button
              className="btn danger"
              disabled={busy}
              onClick={() => (confirming === "reset" ? void doReset() : void doDelete())}
            >
              {busy ? "处理中…" : "确定"}
            </button>
            <button className="btn gray" onClick={() => setConfirming(null)} disabled={busy}>
              取消
            </button>
          </>
        )}
      </div>
    </div>
  );
}

