import { useMemo, useState } from "react";
import { DragPiece, DropSlot } from "../components/DragnDrop";
import { FeedbackLayer, useFeedback } from "../components/Feedback";
import SpeakPrompt from "../components/SpeakPrompt";
import { ShapeKind, ShapeSvg, SHAPE_COLORS } from "../components/Shapes";
import { QUESTION_COUNT, makeRng, shuffle } from "../lib/gameConfig";
import { useRound } from "./useRound";

type Key = "A" | "B" | "C";
type Unit = Key[];

interface PatternQ {
  seq: Key[];
  blanks: number[];
  palette: Record<Key, string>;
  shapeFor: Record<Key, ShapeKind>;
  choices: Key[];
}

const SHAPE_POOL: ShapeKind[] = ["circle", "square", "triangle", "star", "heart", "diamond"];
const KEYS: Key[] = ["A", "B", "C"];

function levelUnit(level: number, rng: () => number): Unit {
  if (level <= 2) return ["A", "B"]; // ABAB
  if (level === 3) return rng() > 0.5 ? ["A", "A", "B"] : ["A", "B", "B"];
  if (level === 4) return ["A", "B", "C"]; // ABC
  return rng() > 0.5 ? ["A", "B", "C"] : ["A", "A", "B", "C"]; // ABC / AABC
}

function buildQuestions(level: number): PatternQ[] {
  const rng = makeRng();
  return Array.from({ length: QUESTION_COUNT[level] ?? 6 }, () => {
    const unit = levelUnit(level, rng);
    const repeats = level <= 2 ? 4 : 3;
    const seq: Key[] = Array.from(
      { length: unit.length * repeats },
      (_, i) => unit[i % unit.length]
    );
    const blankCount = level <= 2 ? 2 : 3;
    // 空白位置放在序列后段（前面已展示足够规律）
    const tailStart = seq.length - unit.length;
    const tailIdx = shuffle(
      Array.from({ length: unit.length }, (_, i) => tailStart + i),
      rng
    ).slice(0, blankCount);
    const blanks = tailIdx.sort((a, b) => a - b);

    const shapes = shuffle(SHAPE_POOL, rng);
    const colors = shuffle(SHAPE_COLORS, rng);
    const shapeFor = {
      A: shapes[0],
      B: shapes[1 % shapes.length],
      C: shapes[2 % shapes.length],
    } as Record<Key, ShapeKind>;
    const palette = {
      A: colors[0].value,
      B: colors[1 % colors.length].value,
      C: colors[2 % colors.length].value,
    } as Record<Key, string>;

    // 选项必须包含所有空格所需答案，再补足 A/B/C
    const choicesSet = new Set(blanks.map((b) => seq[b]));
    KEYS.forEach((k) => choicesSet.add(k));
    const choices = shuffle([...choicesSet], rng);

    return { seq, blanks, palette, shapeFor, choices };
  });
}

export default function Patterns({
  level,
  onDone,
}: {
  level: number;
  onDone: (c: number, t: number) => void;
}) {
  const questions = useMemo(() => buildQuestions(level), [level]);
  const { idx, correct, locked, submit, total } = useRound(questions, onDone);
  const q = questions[idx];
  const fb = useFeedback();
  const [filled, setFilled] = useState<Record<number, Key>>({});

  const onDragEnd = (key: Key, slotId: string | null) => {
    if (!slotId || !slotId.startsWith("blank-")) return;
    const blankPos = Number(slotId.slice(6));
    if (filled[blankPos]) return;
    if (q.seq[blankPos] === key) {
      const next = { ...filled, [blankPos]: key };
      setFilled(next);
      fb.good(document.querySelector(`[data-drop-slot="${slotId}"]`));
      if (q.blanks.every((b) => next[b] != null)) {
        submit(true);
      }
    } else {
      submit(false);
      fb.gentleWrong(document.querySelector(`[data-drag-payload="${key}-piece"]`));
    }
  };

  return (
    <div className="question-area">
      <FeedbackLayer burst={fb.burst} toast={fb.toast} />
      <SpeakPrompt text="找一找规律，把图形拖到空格里补一补" />

      <div className="dnd-row" style={{ maxWidth: 860 }}>
        {q.seq.map((key, i) => {
          const isBlank = q.blanks.includes(i);
          const filledKey = filled[i];
          if (isBlank) {
            return (
              <DropSlot key={i} id={`blank-${i}`} filled={!!filledKey}>
                {filledKey ? (
                  <ShapeSvg kind={q.shapeFor[filledKey]} color={q.palette[filledKey]} />
                ) : (
                  <span style={{ fontSize: 40, color: "#94a3b8" }}>?</span>
                )}
              </DropSlot>
            );
          }
          return (
            <div key={i} className="drag-piece locked">
              <ShapeSvg kind={q.shapeFor[key]} color={q.palette[key]} />
            </div>
          );
        })}
      </div>

      <div className="hint">👇 接下来应该放谁呢 👇</div>

      <div className="dnd-row">
        {q.choices.map((key) => (
          <DragPiece
            key={key}
            payload={`${key}-piece`}
            onDragEnd={(slot) => onDragEnd(key, slot)}
          >
            <ShapeSvg kind={q.shapeFor[key]} color={q.palette[key]} />
          </DragPiece>
        ))}
      </div>

      <div className="hint">
        第 {idx + 1} / {total} 题 · 一次答对 {correct} 题
      </div>
    </div>
  );
}

import { useMemo, useState } from "react";
import { DragPiece, DropSlot } from "../components/DragnDrop";
import { FeedbackLayer, useFeedback } from "../components/Feedback";
import SpeakPrompt from "../components/SpeakPrompt";
import { ShapeKind, ShapeSvg, SHAPE_COLORS, SHAPE_KINDS, SHAPE_NAMES } from "../components/Shapes";
import { QUESTION_COUNT, makeRng, shuffle } from "../lib/gameConfig";
import { useRound } from "./useRound";

interface Piece {
  uid: string;
  kind: ShapeKind;
  color: string;
  colorName?: string;
}

interface ShapeQ {
  /** 是否需要同时匹配形状与颜色 */
  matchColor: boolean;
  slots: Piece[];
  tray: Piece[];
}

function configFor(level: number) {
  switch (level) {
    case 1:
      return { count: 2, color: false, palettes: 1 };
    case 2:
      return { count: 3, color: false, palettes: 1 };
    case 3:
      return { count: 4, color: false, palettes: 2 };
    case 4:
      return { count: 4, color: false, palettes: 3 };
    default:
      return { count: 4, color: true, palettes: 3 };
  }
}

function buildQuestions(level: number): ShapeQ[] {
  const rng = makeRng();
  const cfg = configFor(level);
  return Array.from({ length: QUESTION_COUNT[level] ?? 6 }, () => {
    const kinds = shuffle(SHAPE_KINDS, rng).slice(0, cfg.count) as ShapeKind[];
    const slots: Piece[] = kinds.map((kind, i) => {
      const c = SHAPE_COLORS[i % cfg.palettes];
      return {
        uid: `${kind}-${c.id}-${i}`,
        kind,
        color: c.value,
        colorName: cfg.color ? c.name : undefined,
      };
    });
    // 进阶含颜色匹配：可能出现同形状不同色
    if (cfg.color) {
      const c1 = SHAPE_COLORS[Math.floor(rng() * SHAPE_COLORS.length)];
      const c2 = SHAPE_COLORS[Math.floor(rng() * SHAPE_COLORS.length)];
      slots[0] = { ...slots[0], color: c1.value, colorName: c1.name };
      if (slots[1]) slots[1] = { ...slots[1], color: c2.value, colorName: c2.name };
    }
    return { matchColor: cfg.color, slots, tray: shuffle(slots, rng) };
  });
}

export default function ShapesGame({
  level,
  onDone,
}: {
  level: number;
  onDone: (c: number, t: number) => void;
}) {
  const questions = useMemo(() => buildQuestions(level), [level]);
  const { idx, correct, locked, submit, total } = useRound(questions, onDone);
  const q = questions[idx];
  const fb = useFeedback();
  const [placed, setPlaced] = useState<Record<string, string | null>>({});

  const pieceAtSlot = (slotId: string) =>
    q.tray.find((p) => placed[p.uid] === slotId);

  const onDragEnd = (piece: Piece, overSlot: string | null) => {
    if (!overSlot) return; // 未到槽位，DragPiece 自动回弹
    if (pieceAtSlot(overSlot)) return; // 槽位已有图形，回弹
    const target = q.slots.find((_, i) => `slot-${i}` === overSlot);
    if (!target) return;
    const shapeOk = target.kind === piece.kind;
    const colorOk = !q.matchColor || target.color === piece.color;
    if (shapeOk && colorOk) {
      const next = { ...placed, [piece.uid]: overSlot };
      setPlaced(next);
      fb.good(document.querySelector(`[data-drop-slot="${overSlot}"]`));
      const done = q.slots.every((_, i) =>
        Object.values(next).includes(`slot-${i}`)
      );
      if (done) {
        submit(true);
      }
    } else {
      submit(false);
      fb.gentleWrong(document.querySelector(`[data-drag-payload="${piece.uid}"]`));
    }
  };

  const promptText = q.matchColor
    ? "看一看，把一样形状、一样颜色的图形拖回家"
    : "看一看，把一样的图形拖回家";

  return (
    <div className="question-area">
      <FeedbackLayer burst={fb.burst} toast={fb.toast} />
      <SpeakPrompt text={promptText} />

      <div className="dnd-row">
        {q.slots.map((s, i) => {
          const slotId = `slot-${i}`;
          const piece = pieceAtSlot(slotId);
          return (
            <DropSlot
              key={slotId}
              id={slotId}
              filled={!!piece}
            >
              {piece ? (
                <ShapeSvg kind={piece.kind} color={piece.color} />
              ) : (
                <ShapeSvg kind={s.kind} color={s.color} faded size={64} />
              )}
            </DropSlot>
          );
        })}
      </div>

      <div className="hint">👇 从下面拖上去 👇</div>

      <div className="dnd-row">
        {q.tray.map((p) => (
          <DragPiece
            key={p.uid}
            payload={p.uid}
            locked={!!placed[p.uid]}
            onDragEnd={(slot) => onDragEnd(p, slot)}
          >
            <ShapeSvg kind={p.kind} color={p.color} />
          </DragPiece>
        ))}
      </div>

      <div className="hint">
        {SHAPE_NAMES[q.slots[0]?.kind ?? "circle"]}
        {q.matchColor ? " · 找形状和颜色都一样的位置" : ""} · 第 {idx + 1} / {total} 题 ·
        一次答对 {correct} 题
      </div>
    </div>
  );
}

