import { create } from "zustand";
import type {
  AchievementDef,
  GameStats,
  ItemState,
  Profile,
  RoundResult,
} from "../types";
import { api } from "../lib/api";
import { ACHIEVEMENTS, effectiveLevel } from "../lib/gameConfig";
import { itemsEarnedByStars } from "../lib/items";

interface AppState {
  profiles: Profile[];
  activeProfileId: number | null;
  activeProfile: Profile | null;
  loading: boolean;

  stats: GameStats | null;
  records: import("../types").GameRecord[];
  achievementCodes: Set<string>;
  items: ItemState | null;
  /** 本回合新弹出的成就/饰品，供奖励页展示 */
  lastRound: RoundResult | null;
  newAchievements: AchievementDef[];
  newItems: string[];

  boot: () => Promise<void>;
  refreshProfiles: () => Promise<void>;
  selectProfile: (id: number) => Promise<void>;
  createProfile: (input: {
    nickname: string;
    birthday: string;
    avatar: string;
  }) => Promise<Profile>;
  updateProfile: (id: number, input: {
    nickname: string;
    birthday: string;
    avatar: string;
  }) => Promise<void>;
  setLevelOverride: (id: number, level: number | null) => Promise<void>;
  deleteProfile: (id: number, pin: string) => Promise<void>;
  resetProgress: (id: number, pin: string) => Promise<void>;

  /** 游戏结束：保存记录、刷星星、检查成就与饰品 */
  finishRound: (r: RoundResult) => Promise<{ starsTotal: number }>;
  refreshProfileData: () => Promise<void>;
  equip: (slot: "hat" | "glasses" | "background" | "pet", code: string | null) => Promise<void>;
}

const ACTIVE_KEY = "kidmath.activeProfile";

function readActiveId(): number | null {
  const v = localStorage.getItem(ACTIVE_KEY);
  return v ? Number(v) : null;
}

export const useStore = create<AppState>((set, get) => ({
  profiles: [],
  activeProfileId: null,
  activeProfile: null,
  loading: true,
  stats: null,
  records: [],
  achievementCodes: new Set(),
  items: null,
  lastRound: null,
  newAchievements: [],
  newItems: [],

  boot: async () => {
    const profiles = await api.listProfiles();
    let activeId = readActiveId();
    if (activeId != null && !profiles.some((p) => p.id === activeId)) {
      activeId = null;
      localStorage.removeItem(ACTIVE_KEY);
    }
    set({ profiles, activeProfileId: activeId, loading: false });
    if (activeId != null) {
      await get().selectProfile(activeId);
    }
  },

  refreshProfiles: async () => {
    const profiles = await api.listProfiles();
    const cur = get().activeProfile;
    set({
      profiles,
      activeProfile: cur ? profiles.find((p) => p.id === cur.id) ?? null : null,
    });
  },

  selectProfile: async (id) => {
    localStorage.setItem(ACTIVE_KEY, String(id));
    const profile = get().profiles.find((p) => p.id === id) ?? null;
    set({ activeProfileId: id, activeProfile: profile });
    await get().refreshProfileData();
  },

  createProfile: async (input) => {
    const p = await api.createProfile(input);
    await get().refreshProfiles();
    return p;
  },

  updateProfile: async (id, input) => {
    await api.updateProfile(id, input);
    await get().refreshProfiles();
    const p = get().profiles.find((x) => x.id === id);
    if (get().activeProfileId === id && p) {
      set({ activeProfile: p });
    }
  },

  setLevelOverride: async (id, level) => {
    await api.setLevelOverride(id, level);
    await get().refreshProfiles();
    const p = get().profiles.find((x) => x.id === id);
    if (get().activeProfileId === id && p) set({ activeProfile: p });
  },

  deleteProfile: async (id, pin) => {
    await api.deleteProfile(id, pin);
    await get().refreshProfiles();
    if (get().activeProfileId === id) {
      localStorage.removeItem(ACTIVE_KEY);
      set({
        activeProfileId: null,
        activeProfile: null,
        stats: null,
        records: [],
        achievementCodes: new Set(),
        items: null,
      });
    }
  },

  resetProgress: async (id, pin) => {
    await api.resetProgress(id, pin);
    await get().refreshProfiles();
    if (get().activeProfileId === id) await get().refreshProfileData();
  },

  refreshProfileData: async () => {
    const { activeProfileId } = get();
    if (activeProfileId == null) return;
    const [stats, records, achievements, items, profiles] = await Promise.all([
      api.getStats(activeProfileId),
      api.listRecords(activeProfileId, 200),
      api.listAchievements(activeProfileId),
      api.listItems(activeProfileId),
      api.listProfiles(),
    ]);
    const profile = profiles.find((p) => p.id === activeProfileId) ?? get().activeProfile;
    set({
      stats,
      records,
      achievementCodes: new Set(achievements.map((a) => a.code)),
      items,
      profiles,
      activeProfile: profile,
    });
  },

  finishRound: async (r) => {
    const profile = get().activeProfile;
    if (!profile) throw new Error("没有活动档案");
    const level = effectiveLevel(profile);

    const saved = await api.saveResult({
      profile_id: profile.id,
      game_type: r.gameType,
      level: r.level ?? level,
      correct: r.correct,
      total: r.total,
      stars_earned: r.stars,
    });

    // 刷新统计后再判定成就
    await get().refreshProfileData();
    const { stats, records, items } = get();

    // ---------- 成就判定（前端计算，后端幂等解锁） ----------
    const codes = new Set<string>();
    codes.add("first_round");
    if ((stats?.rounds ?? 0) >= 10) codes.add("rounds_10");
    if ((stats?.total_correct ?? 0) >= 50) codes.add("correct_50");
    if ((stats?.played_games ?? 0) >= 6) codes.add("all_games");
    if (r.correct === r.total) codes.add("perfect_game");
    // 连续 3 天：看最近记录日期
    const days = new Set(
      records.slice(0, 30).map((rec) => rec.played_at.slice(0, 10))
    );
    if (hasThreeDayStreak([...days])) codes.add("streak_3days");

    const newlyUnlocked: AchievementDef[] = [];
    for (const code of codes) {
      const isNew = await api.unlockAchievement(profile.id, code);
      if (isNew) {
        const def = ACHIEVEMENTS.find((a) => a.code === code);
        if (def) newlyUnlocked.push(def);
      }
    }

    // ---------- 饰品：按最新总星星同步 ----------
    const starsTotal = saved.stars_total;
    const expected = itemsEarnedByStars(starsTotal).map((i) => i.code);
    const newItemCodes = await api.syncItems(profile.id, expected);
    const already = new Set(items?.unlocked.map((u) => u.item_code) ?? []);
    const brandNew = newItemCodes.filter((c) => !already.has(c));

    await get().refreshProfileData();
    set({
      lastRound: r,
      newAchievements: newlyUnlocked,
      newItems: brandNew,
    });
    return { starsTotal };
  },

  equip: async (slot, code) => {
    const profile = get().activeProfile;
    if (!profile || !get().items) return;
    const outfit = {
      hat: get().items!.outfit.hat,
      glasses: get().items!.outfit.glasses,
      background: get().items!.outfit.background,
      pet: get().items!.outfit.pet,
      [slot]: code,
    } as ItemState["outfit"];
    await api.setOutfit(profile.id, outfit);
    await get().refreshProfileData();
  },
}));

/** 判断日期集合中是否存在连续 3 天（含今天） */
  if (days.length < 3) return false;
  const set = new Set(days);
  const today = new Date();
  for (let offset = 0; offset <= 2; offset++) {
    let ok = true;
    for (let back = 0; back < 3; back++) {
      const d = new Date(today);
      d.setDate(d.getDate() - offset - back);
      const key = d.toISOString().slice(0, 10);
      if (!set.has(key)) {
        ok = false;
        break;
      }
    }
    if (ok) return true;
  }
  return false;
}

/** 供游戏组件获取当前 Level */
export function useLevel(game?: GameType): number {
  const p = useStore((s) => s.activeProfile);
  if (!p) return 1;
  return effectiveLevel(p);
}

import { useMemo, useState } from "react";
import { DragPiece, DropSlot } from "../components/DragnDrop";
import { FeedbackLayer, useFeedback } from "../components/Feedback";
import SpeakPrompt from "../components/SpeakPrompt";
import { ShapeKind, ShapeSvg, SHAPE_COLORS } from "../components/Shapes";
import { QUESTION_COUNT, makeRng, shuffle } from "../lib/gameConfig";
import { useRound } from "./useRound";

type Key = "A" | "B" | "C";
type Unit = Key[];

interface PatternQ {
  seq: Key[];
  blanks: number[];
  palette: Record<Key, string>;
  shapeFor: Record<Key, ShapeKind>;
  choices: Key[];
}

const SHAPE_POOL: ShapeKind[] = ["circle", "square", "triangle", "star", "heart", "diamond"];
const KEYS: Key[] = ["A", "B", "C"];

function levelUnit(level: number, rng: () => number): Unit {
  if (level <= 2) return ["A", "B"]; // ABAB
  if (level === 3) return rng() > 0.5 ? ["A", "A", "B"] : ["A", "B", "B"];
  if (level === 4) return ["A", "B", "C"]; // ABC
  return rng() > 0.5 ? ["A", "B", "C"] : ["A", "A", "B", "C"]; // ABC / AABC
}

function buildQuestions(level: number): PatternQ[] {
  const rng = makeRng();
  return Array.from({ length: QUESTION_COUNT[level] ?? 6 }, () => {
    const unit = levelUnit(level, rng);
    const repeats = level <= 2 ? 4 : 3;
    const seq: Key[] = Array.from(
      { length: unit.length * repeats },
      (_, i) => unit[i % unit.length]
    );
    const blankCount = level <= 2 ? 2 : 3;
    // 空白位置放在序列后段（前面已展示足够规律）
    const tailStart = seq.length - unit.length;
    const tailIdx = shuffle(
      Array.from({ length: unit.length }, (_, i) => tailStart + i),
      rng
    ).slice(0, blankCount);
    const blanks = tailIdx.sort((a, b) => a - b);

    const shapes = shuffle(SHAPE_POOL, rng);
    const colors = shuffle(SHAPE_COLORS, rng);
    const shapeFor = {
      A: shapes[0],
      B: shapes[1 % shapes.length],
      C: shapes[2 % shapes.length],
    } as Record<Key, ShapeKind>;
    const palette = {
      A: colors[0].value,
      B: colors[1 % colors.length].value,
      C: colors[2 % colors.length].value,
    } as Record<Key, string>;

    // 选项必须包含所有空格所需答案，再补足 A/B/C
    const choicesSet = new Set(blanks.map((b) => seq[b]));
    KEYS.forEach((k) => choicesSet.add(k));
    const choices = shuffle([...choicesSet], rng);

    return { seq, blanks, palette, shapeFor, choices };
  });
}

export default function Patterns({
  level,
  onDone,
}: {
  level: number;
  onDone: (c: number, t: number) => void;
}) {
  const questions = useMemo(() => buildQuestions(level), [level]);
  const { idx, correct, submit, total } = useRound(questions, onDone);
  const q = questions[idx];
  const fb = useFeedback();
  const [filled, setFilled] = useState<Record<number, Key>>({});

  const onDragEnd = (key: Key, slotId: string | null) => {
    if (!slotId || !slotId.startsWith("blank-")) return;
    const blankPos = Number(slotId.slice(6));
    if (filled[blankPos]) return;
    if (q.seq[blankPos] === key) {
      const next = { ...filled, [blankPos]: key };
      setFilled(next);
      fb.good(document.querySelector(`[data-drop-slot="${slotId}"]`));
      if (q.blanks.every((b) => next[b] != null)) {
        submit(true);
      }
    } else {
      submit(false);
      fb.gentleWrong(document.querySelector(`[data-drag-payload="${key}-piece"]`));
    }
  };

  return (
    <div className="question-area">
      <FeedbackLayer burst={fb.burst} toast={fb.toast} />
      <SpeakPrompt text="找一找规律，把图形拖到空格里补一补" />

      <div className="dnd-row" style={{ maxWidth: 860 }}>
        {q.seq.map((key, i) => {
          const isBlank = q.blanks.includes(i);
          const filledKey = filled[i];
          if (isBlank) {
            return (
              <DropSlot key={i} id={`blank-${i}`} filled={!!filledKey}>
                {filledKey ? (
                  <ShapeSvg kind={q.shapeFor[filledKey]} color={q.palette[filledKey]} />
                ) : (
                  <span style={{ fontSize: 40, color: "#94a3b8" }}>?</span>
                )}
              </DropSlot>
            );
          }
          return (
            <div key={i} className="drag-piece locked">
              <ShapeSvg kind={q.shapeFor[key]} color={q.palette[key]} />
            </div>
          );
        })}
      </div>

      <div className="hint">👇 接下来应该放谁呢 👇</div>

      <div className="dnd-row">
        {q.choices.map((key) => (
          <DragPiece
            key={key}
            payload={`${key}-piece`}
            onDragEnd={(slot) => onDragEnd(key, slot)}
          >
            <ShapeSvg kind={q.shapeFor[key]} color={q.palette[key]} />
          </DragPiece>
        ))}
      </div>

      <div className="hint">
        第 {idx + 1} / {total} 题 · 一次答对 {correct} 题
      </div>
    </div>
  );
}

