  const questions = useMemo(() => buildQuestions(level), [level]);
  const { idx, correct, submit, total } = useRound(questions, onDone);
  const q = questions[idx];
  const fb = useFeedback();
  const [filled, setFilled] = useState<Record<number, Key>>({});

  const onDragEnd = (key: Key, slotId: string | null) => {
    if (!slotId || !slotId.startsWith("blank-")) return;
    const blankPos = Number(slotId.slice(6));
    if (filled[blankPos]) return;
    if (q.seq[blankPos] === key) {
      const next = { ...filled, [blankPos]: key };
      setFilled(next);
      fb.good(document.querySelector(`[data-drop-slot="${slotId}"]`) as HTMLElement | null);
      if (q.blanks.every((b) => next[b] != null)) {
        submit(true);
      }
    } else {
      submit(false);
      fb.gentleWrong(document.querySelector(`[data-drag-payload="${key}-piece"]`));
    }
  };

  return (
    <div className="question-area">
      <FeedbackLayer burst={fb.burst} toast={fb.toast} />
      <SpeakPrompt text="找一找规律，把图形拖到空格里补一补" />

      <div className="dnd-row" style={{ maxWidth: 860 }}>
        {q.seq.map((key, i) => {
          const isBlank = q.blanks.includes(i);
          const filledKey = filled[i];
          if (isBlank) {
            return (
              <DropSlot key={i} id={`blank-${i}`} filled={!!filledKey}>
                {filledKey ? (
                  <ShapeSvg kind={q.shapeFor[filledKey]} color={q.palette[filledKey]} />
                ) : (
                  <span style={{ fontSize: 40, color: "#94a3b8" }}>?</span>
                )}
              </DropSlot>
            );
          }
          return (
            <div key={i} className="drag-piece locked">
              <ShapeSvg kind={q.shapeFor[key]} color={q.palette[key]} />
            </div>
          );
        })}
      </div>

      <div className="hint">👇 接下来应该放谁呢 👇</div>

      <div className="dnd-row">
        {q.choices.map((key) => (
          <DragPiece
            key={key}
            payload={`${key}-piece`}
            onDragEnd={(slot) => onDragEnd(key, slot)}
          >
            <ShapeSvg kind={q.shapeFor[key]} color={q.palette[key]} />
          </DragPiece>
        ))}
      </div>

      <div className="hint">
        第 {idx + 1} / {total} 题 · 一次答对 {correct} 题
      </div>
    </div>
  );
}

import { useMemo, useState } from "react";
import { DragPiece, DropSlot } from "../components/DragnDrop";
import { FeedbackLayer, useFeedback } from "../components/Feedback";
import SpeakPrompt from "../components/SpeakPrompt";
import { ShapeKind, ShapeSvg, SHAPE_COLORS, SHAPE_KINDS, SHAPE_NAMES } from "../components/Shapes";
import { QUESTION_COUNT, makeRng, shuffle } from "../lib/gameConfig";
import { useRound } from "./useRound";

interface Piece {
  uid: string;
  kind: ShapeKind;
  color: string;
  colorName?: string;
}

interface ShapeQ {
  /** 是否需要同时匹配形状与颜色 */
  matchColor: boolean;
  slots: Piece[];
  tray: Piece[];
}

function configFor(level: number) {
  switch (level) {
    case 1:
      return { count: 2, color: false, palettes: 1 };
    case 2:
      return { count: 3, color: false, palettes: 1 };
    case 3:
      return { count: 4, color: false, palettes: 2 };
    case 4:
      return { count: 4, color: false, palettes: 3 };
    default:
      return { count: 4, color: true, palettes: 3 };
  }
}

function buildQuestions(level: number): ShapeQ[] {
  const rng = makeRng();
  const cfg = configFor(level);
  return Array.from({ length: QUESTION_COUNT[level] ?? 6 }, () => {
    const kinds = shuffle(SHAPE_KINDS, rng).slice(0, cfg.count) as ShapeKind[];
    const slots: Piece[] = kinds.map((kind, i) => {
      const c = SHAPE_COLORS[i % cfg.palettes];
      return {
        uid: `${kind}-${c.id}-${i}`,
        kind,
        color: c.value,
        colorName: cfg.color ? c.name : undefined,
      };
    });
    // 进阶含颜色匹配：可能出现同形状不同色
    if (cfg.color) {
      const c1 = SHAPE_COLORS[Math.floor(rng() * SHAPE_COLORS.length)];
      const c2 = SHAPE_COLORS[Math.floor(rng() * SHAPE_COLORS.length)];
      slots[0] = { ...slots[0], color: c1.value, colorName: c1.name };
      if (slots[1]) slots[1] = { ...slots[1], color: c2.value, colorName: c2.name };
    }
    return { matchColor: cfg.color, slots, tray: shuffle(slots, rng) };
  });
}

export default function ShapesGame({
  level,
  onDone,
}: {
  level: number;
  onDone: (c: number, t: number) => void;
}) {
