                navigate(`/game/${g.type}`);
              }}
            >
              <span className="gicon">{g.emoji}</span>
              <span className="gname">{g.name}</span>
              <span className="gdesc">{g.desc}</span>
              <span className="level-badge">Level {level}</span>
            </button>
          ))}
