function boundsFor(level: number) {
  // 10 以内起步，高 Level 到 20 以内
  switch (level) {
    case 1:
      return { max: 5, ops: ["+"] as ("+" | "-")[] };
    case 2:
      return { max: 10, ops: ["+", "-"] as ("+" | "-")[] };
    case 3:
      return { max: 10, ops: ["+", "-"] as ("+" | "-")[] };
    case 4:
      return { max: 15, ops: ["+", "-"] as ("+" | "-")[] };
    default:
      return { max: 20, ops: ["+", "-"] as ("+" | "-")[] };
  }
}

export function buildQuestions(level: number): OrchardQ[] {
  const rng = makeRng();
  const { max, ops } = boundsFor(level);
