    fn pin_hash_is_salted_and_stable() {
        assert_eq!(hash_pin("0000"), hash_pin("0000"));
        assert_ne!(hash_pin("0000"), hash_pin("1234"));
        // 加盐后不能等于裸 sha256("0000")
