8	interface FishQ {
9	  count: number;
10	  fish: { emoji: string; top: number; left: number; delay: number; flip: boolean }[];
11	  choices: number[];
12	}
13	
14	const FISH_EMOJIS = ["🐟", "🐠", "🐡", "🦈", "🐙"];
15	
16	function maxByLevel(level: number) {
17	  return [3, 5, 9, 12, 20][level - 1] ?? 5;
18	}
