20	export function buildQuestions(level: number): FishQ[] {
21	  const rng = makeRng();
22	  const n = QUESTION_COUNT[level] ?? 6;
23	  return Array.from({ length: n }, () => {
24	    const max = maxByLevel(level);
25	    const count = randInt(1, max, rng);
26	    // 可选数字范围为 1..max，选项数不能超过范围大小
27	    const optionCount = Math.min(level <= 2 ? 3 : 4, max);
28	    const choiceSet = new Set<number>([count]);
29	    let guard = 0;
30	    while (choiceSet.size < optionCount && guard++ < 200) {
31	      const c = count + randInt(-2, 2, rng);
32	      if (c >= 1 && c <= max) choiceSet.add(c);
33	    }
34	    guard = 0;
35	    while (choiceSet.size < optionCount && guard++ < 200) {
36	      choiceSet.add(randInt(1, max, rng));
37	    }
38	    // 在隐形网格里随机布点，减少鱼之间的重叠
39	    const cols = 5;
40	    const rows = 4;
41	    const cells = shuffle(
42	      Array.from({ length: cols * rows }, (_, i) => i),
43	      rng
44	    ).slice(0, count);
45	    const fish = cells.map((cell) => {
46	      const col = cell % cols;
47	      const row = Math.floor(cell / cols);
48	      return {
49	        emoji: FISH_EMOJIS[randInt(0, FISH_EMOJIS.length - 1, rng)],
50	        top: 6 + row * (82 / rows) + rng() * 6,
51	        left: 3 + col * (90 / cols) + rng() * 5,
52	        delay: rng() * 2,
53	        flip: rng() > 0.5,
54	      };
55	    });
56	    return {
57	      count,
58	      fish,
59	      choices: [...choiceSet].sort((a, b) => a - b),
60	    };
61	  });
62	}
