      attemptsRef.current = 0;
      setAttempts(0);
      lockedRef.current = false;
      setLocked(false);
      if (idxRef.current >= total - 1) {
        onDoneRef.current(correctRef.current, total);
      } else {
        idxRef.current += 1;
        setIdx(idxRef.current);
      }
    }, 780);
    return "right";
  },
  [total]
