1	import { useMemo } from "react";
2	import { FeedbackLayer, useFeedback } from "../components/Feedback";
3	import SpeakPrompt from "../components/SpeakPrompt";
4	import { QUESTION_COUNT, makeRng, pick, randInt, shuffle } from "../lib/gameConfig";
5	import { useRound } from "./useRound";
6	
7	interface OrchardQ {
8	  text: string;
9	  answer: number;
10	  emoji: string;
11	  base: number;
12	  delta: number;
13	  op: "+" | "-";
14	  choices: number[];
15	}
16	
17	const FRUITS = [
18	  { emoji: "🍎", name: "苹果" },
19	  { emoji: "🍊", name: "橘子" },
20	  { emoji: "🍐", name: "梨" },
21	  { emoji: "🍑", name: "桃子" },
22	  { emoji: "🍓", name: "草莓" },
23	];
24	
25	function boundsFor(level: number) {
26	  // 10 以内起步，高 Level 到 20 以内
27	  switch (level) {
28	    case 1:
29	      return { max: 10, ops: ["+"] as ("+" | "-")[] };
30	    case 2:
31	      return { max: 10, ops: ["+", "-"] as ("+" | "-")[] };
32	    case 3:
33	      return { max: 15, ops: ["+", "-"] as ("+" | "-")[] };
34	    case 4:
35	      return { max: 20, ops: ["+", "-"] as ("+" | "-")[] };
36	    default:
37	      return { max: 20, ops: ["+", "-"] as ("+" | "-")[] };
38	  }
39	}
40	
41	export function buildQuestions(level: number): OrchardQ[] {
42	  const rng = makeRng();
43	  const { max, ops } = boundsFor(level);
44	  return Array.from({ length: QUESTION_COUNT[level] ?? 6 }, () => {
45	    const fruit = pick(FRUITS, rng);
46	    const op = pick(ops, rng);
47	    let a: number;
48	    let b: number;
49	    let answer: number;
50	    let text: string;
51	    if (op === "+") {
52	      a = randInt(1, max - 1, rng);
53	      b = randInt(1, max - a, rng);
54	      answer = a + b;
55	      text = `果树上原来有 ${a} 个${fruit.name}，又长出来 ${b} 个，现在一共有几个${fruit.name}？`;
56	    } else {
57	      a = randInt(2, max, rng);
58	      b = randInt(1, a - 1, rng);
59	      answer = a - b;
60	      text = `果树上有 ${a} 个${fruit.name}，小朋友摘走了 ${b} 个，还剩几个${fruit.name}？`;
61	    }
62	    const choiceSet = new Set<number>([answer]);
63	    while (choiceSet.size < 4) {
64	      const c = answer + randInt(-3, 3, rng);
65	      if (c >= 0 && c <= max + 2) choiceSet.add(c);
66	    }
67	    return {
68	      text,
69	      answer,
70	      emoji: fruit.emoji,
71	      base: a,
72	      delta: b,
73	      op,
74	      choices: shuffle([...choiceSet], rng),
75	    };
76	  });
77	}
78	
79	export default function Orchard({
80	  level,
81	  onDone,
82	  onProgress,
