103	    ? Math.max(q.base, q.answer)
104	    : q.base;
105	
106	  return (
107	    <div className="question-area">
108	      <FeedbackLayer burst={fb.burst} toast={fb.toast} />
109	      <SpeakPrompt text={q.text} />
110	
111	      <div className="orchard-scene">🌳</div>
112	      <div className="fruit-line" aria-hidden>
113	        {Array.from({ length: shownCount }, (_, i) => (
114	          <span
115	            key={i}
116	            className={`f ${
117	              showResult && q.op === "+" && i >= q.base ? "added" : ""
118	            } ${showResult && q.op === "-" && i >= q.answer ? "taken" : ""}`}
119	          >
120	            {q.emoji}
121	          </span>
122	        ))}
123	      </div>
124	      {!showResult && (
125	        <div className="hint">
126	          {q.op === "+" ? `再加 ${q.delta} 个` : `摘走 ${q.delta} 个`}
127	        </div>
128	      )}
129	
130	      <div className="answer-row">
131	        {q.choices.map((c) => (
132	          <button
133	            key={c}
134	            className="answer-btn"
135	            onClick={(e) => choose(c, e.currentTarget)}
136	          >
137	            {c}
138	          </button>
139	        ))}
140	      </div>
141	
142	      <div className="hint">
