            <SummaryPill label="获得星星" value={`⭐ ${totalStars}`} bg="#fce7f3" />
            <SummaryPill
              label="今日时长"
              value={`${Math.floor(usedSeconds / 60)}分${usedSeconds % 60}秒`}
              bg="#f1f5f9"
            />
          </div>
          <table className="stat-table">
            <thead>
              <tr>
                <th>游戏</th>
                <th>回合数</th>
                <th>答对题数</th>
                <th>正确率</th>
                <th>获得星星</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => {
                const g = meta.get(r.game_type);
                const a = r.total ? Math.round((r.correct / r.total) * 100) : 0;
                return (
                  <tr key={r.game_type}>
                    <td>
                      {g?.emoji ?? "🎮"} {g?.name ?? r.game_type}
                    </td>
                    <td>{r.rounds}</td>
                    <td>
                      {r.correct} / {r.total}
                    </td>
                    <td>{a}%</td>
                    <td>⭐ {r.stars}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </>
      )}

      {exportMsg && (
        <div
          className="hint"
          style={{
            marginTop: 10,
